21	// 构造 CostModel：所有算法 count 初始化为 1
22	static CostModel BuildCostModel(const std::vector<std::string>& algoNames)
23	{
24	    CostModel cm;
25	    cm.count = static_cast<int>(algoNames.size());
26	    cm.costAlgoParams = new CostAlgoParams[algoNames.size()];
27	    for (size_t i = 0; i < algoNames.size(); i++) {
28	        cm.costAlgoParams[i].algName = strdup(algoNames[i].c_str());
29	        cm.costAlgoParams[i].param = nullptr;
30	        cm.costAlgoParams[i].count = 1;
31	    }
32	    return cm;
33	}
34	
35	// 释放 CostModel
36	static void FreeCostModel(CostModel& cm)
37	{
38	    for (int i = 0; i < cm.count; i++) {
39	        free(const_cast<char*>(cm.costAlgoParams[i].algName));
40	    }
41	    delete[] cm.costAlgoParams;
42	    cm.costAlgoParams = nullptr;
43	    cm.count = 0;
44	}
45	
46	// 按算法名查找 count（0=被排除，1=正常，-1=不存在）
47	static int GetAlgoCount(const CostModel& cm, const std::string& name)
48	{
49	    for (int i = 0; i < cm.count; i++) {
50	        if (cm.costAlgoParams[i].algName && name == cm.costAlgoParams[i].algName) {
51	            return cm.costAlgoParams[i].count;
52	        }
53	    }
54	    return -1; // 未找到
55	}
