71	HcclResult TaskCheckOpSemantics::CheckBufSemantics(
72	    std::vector<BufferSemantic*>& bufSemantics, u64 startAddr, u64 size, bool ignoreError) const
73	{
74	    if (bufSemantics.size() == 0) {
75	        if (!ignoreError) {
76	            HCCL_ERROR("When check buf semantics in range, buf semantics to check is empty");
77	        } else {
78	            HCCL_WARNING("When check buf semantics in range, buf semantics to check is empty");
79	        }
80	
81	        return HcclResult::HCCL_E_PARA;
82	    }
83	
84	    u64 totalSize = 0;
85	    BufferSemantic* pre = bufSemantics[0];
86	    // 头部有空档
87	    if (pre->startAddr > startAddr) {
88	        if (!ignoreError) {
89	            HCCL_ERROR(
90	                "When check buf semantics in range, there is blank in head."
91	                "startAddr should be %llu, while first semantic startAddr is %llu",
92	                startAddr, pre->startAddr);
93	        } else {
94	            HCCL_WARNING(
95	                "When check buf semantics in range, there is blank in head."
96	                "startAddr should be %llu, while first semantic startAddr is %llu",
97	                startAddr, pre->startAddr);
98	        }
99	
100	        return HcclResult::HCCL_E_PARA;
101	    }
102	    if (pre->startAddr + pre->size >= startAddr + size) {
103	        totalSize += size;
104	    } else {
105	        totalSize += pre->startAddr + pre->size - startAddr;
106	    }
107	
108	    for (size_t index = 1; index < bufSemantics.size(); index++) {
109	        BufferSemantic* cur = bufSemantics[index];
110	        if (cur->startAddr != pre->startAddr + pre->size) {
111	            if (!ignoreError) {
112	                HCCL_ERROR(
113	                    "there is blank in middle, pre semantic endAddr is %llu, cur semantic startAddr is %llu,"
114	                    "they should be equal",
115	                    pre->startAddr + pre->size, cur->startAddr);
116	            } else {
117	                HCCL_WARNING(
118	                    "there is blank in middle, pre semantic endAddr is %llu, cur semantic startAddr is %llu,"
119	                    "they should be equal",
120	                    pre->startAddr + pre->size, cur->startAddr);
121	            }
122	
123	            return HcclResult::HCCL_E_PARA;
124	        }
125	        if (cur->startAddr + cur->size >= startAddr + size) {
126	            totalSize += startAddr + size - cur->startAddr;
127	        } else {
128	            totalSize += cur->size;
129	        }
130	
131	        pre = cur;
132	    }
133	
134	    if (totalSize != size) {
135	        if (!ignoreError) {
136	            HCCL_ERROR(
137	                "When check buf semantics in range, there is blank in tail."
138	                "endAddr should be %llu, while last semantic endAddr is %llu",
139	                startAddr + size, startAddr + totalSize);
140	        } else {
141	            HCCL_WARNING(
142	                "When check buf semantics in range, there is blank in tail."
143	                "endAddr should be %llu, while last semantic endAddr is %llu",
144	                startAddr + size, startAddr + totalSize);
145	        }
146	
147	        return HcclResult::HCCL_E_PARA;
148	    }
149	
150	    return HcclResult::HCCL_SUCCESS;
151	}
