154	void TaskCheckOpSemantics::GetSrcIntersectionAddr(
155	    SliceOpPair& slicePair, const BufferSemantic& srcBufSemantic, u64& srcStartAddr, u64& srcEndAddr) const
156	{
157	    srcStartAddr = slicePair.srcSlice.GetOffset();
158	    srcEndAddr = srcStartAddr + slicePair.srcSlice.GetSize();
159	    if (srcBufSemantic.startAddr > srcStartAddr) {
160	        srcStartAddr = srcBufSemantic.startAddr;
161	    }
162	    if (srcBufSemantic.startAddr + srcBufSemantic.size < srcEndAddr) {
163	        srcEndAddr = srcBufSemantic.startAddr + srcBufSemantic.size;
164	    }
165	    return;
166	}
