168	void TaskCheckOpSemantics::GetAffectedBufSemantics(
169	    SliceOpPair& slicePair, const BufferSemantic& srcBufSemantic, std::vector<BufferSemantic*>& affectedDstBufSemantics)
170	{
171	    u64 srcStartAddr;
172	    u64 srcEndAddr;
