182	    for (auto& ele : allRankMemSemantics_[dstRank][dstBufType]) {
183	        if (ele.startAddr + ele.size <= dstStartAddr) {
184	            continue;
185	        }
186	        if (ele.startAddr >= dstEndAddr) {
187	            continue;
188	        }
