215	// 因为srcBufSemantic与affectedDstBufSemantics可能会有重叠，affectedDstBufSemantics处理过程中会被修改，因此srcBufSemantic不能传引用
216	void TaskCheckOpSemantics::ApplyOverrideSrcBufSemantic(SliceOpPair& slicePair, const BufferSemantic srcBufSemantic)
217	{
218	    u64 srcStartAddr;
219	    u64 srcEndAddr;
220	    GetSrcIntersectionAddr(slicePair, srcBufSemantic, srcStartAddr, srcEndAddr);
221	
222	    s64 dstSrcOffset = slicePair.dstSlice.GetOffset() - slicePair.srcSlice.GetOffset();
223	    u64 dstStartAddr = srcStartAddr + dstSrcOffset;
224	    u64 dstEndAddr = srcEndAddr + dstSrcOffset;
225	
226	    RankId dstRank = slicePair.dstRank;
227	    BufferType dstBufType = slicePair.dstSlice.GetType();
228	    std::set<BufferSemantic>& targetBufferSemantic = allRankMemSemantics_[dstRank][dstBufType];
229	
230	    BufferSemantic dstBufSemantic(
231	        dstStartAddr, dstEndAddr - dstStartAddr, srcBufSemantic.isReduce, srcBufSemantic.reduceType,
232	        srcBufSemantic.srcBufs);
233	    // 因为可能使用的是srcBufSemantic的一部分，所以这边需要处理一下源地址
234	    for (auto& srcBuf : dstBufSemantic.srcBufs) {
235	        srcBuf.srcAddr += srcStartAddr - srcBufSemantic.startAddr;
236	    }
237	    dstBufSemantic.affectedGlobalSteps.push_back(globalStep_);
238	
239	    targetBufferSemantic.insert(dstBufSemantic);
240	
241	    return;
242	}
