244	HcclResult TaskCheckOpSemantics::ReduceToAffectedBufSemantic(
245	    const BufferSemantic& srcBufSemantic, std::vector<BufferSemantic*> toAddReduceInfoSemantics, u64 srcStartAddr)
246	{
247	    u64 srcOffset = srcStartAddr - srcBufSemantic.startAddr;
248	    for (auto& ele : toAddReduceInfoSemantics) {
249	        if (ele->srcBufs.size() == 1) {
250	            if (ele->isReduce == true) {
251	                HCCL_ERROR("buffer semantic srcBufs size is 1, but isReduce is true");
252	                HCCL_ERROR("invalid buffer semantic is %s", ele->Describe().c_str());
253	                return HcclResult::HCCL_E_PARA;
254	            }
255	            ele->isReduce = true;
256	            ele->reduceType = reduceType_;
257	        }
258	        if (srcBufSemantic.srcBufs.size() > 1 && ele->reduceType != srcBufSemantic.reduceType) {
259	            HCCL_ERROR("reduceType is different");
260	            HCCL_ERROR("src buf semantic is %s", srcBufSemantic.Describe().c_str());
261	            HCCL_ERROR("dst buf semantic is %s", ele->Describe().c_str());
262	            return HcclResult::HCCL_E_PARA;
263	        }
264	
265	        for (auto srcBuf : srcBufSemantic.srcBufs) {
266	            // 校验重复reduce的场景
267	            srcBuf.srcAddr += srcOffset;
268	            u32 beforeInsertCnt = ele->srcBufs.size();
269	            ele->srcBufs.insert(srcBuf);
270	            u32 afterInsertCnt = ele->srcBufs.size();
271	            if (beforeInsertCnt == afterInsertCnt) {
272	                HCCL_ERROR(
273	                    "after add reduce srcBuf %s, the size of dst srcBufs not changed", srcBuf.Describe().c_str());
274	                HCCL_ERROR("src buf semantic is %s", srcBufSemantic.Describe().c_str());
275	                HCCL_ERROR("dst buf semantic is %s", ele->Describe().c_str());
276	                return HcclResult::HCCL_E_PARA;
277	            }
278	        }
279	
280	        // 用于图形化界面展示，添加影响的节点
281	        ele->affectedGlobalSteps.insert(
282	            ele->affectedGlobalSteps.end(), srcBufSemantic.affectedGlobalSteps.begin(),
283	            srcBufSemantic.affectedGlobalSteps.end());
284	        srcOffset += ele->size;
285	    }
286	    return HcclResult::HCCL_SUCCESS;
287	}
288	
289	HcclResult TaskCheckOpSemantics::ApplyReduceSrcBufSemantic(
290	    SliceOpPair& slicePair, const BufferSemantic& srcBufSemantic, std::vector<BufferSemantic*>& affectedDstBufSemantics)
291	{
292	    u64 srcStartAddr;
293	    u64 srcEndAddr;
294	    GetSrcIntersectionAddr(slicePair, srcBufSemantic, srcStartAddr, srcEndAddr);
295	
296	    s64 dstSrcOffset = slicePair.dstSlice.GetOffset() - slicePair.srcSlice.GetOffset();
297	    u64 dstStartAddr = srcStartAddr + dstSrcOffset;
298	    u64 dstEndAddr = srcEndAddr + dstSrcOffset;
299	
300	    // 校验目的地是否已经有了数据
301	    auto ret = CheckBufSemantics(affectedDstBufSemantics, dstStartAddr, dstEndAddr - dstStartAddr);
302	    if (ret != HcclResult::HCCL_SUCCESS) {
303	        HCCL_ERROR(
304	            "failed to check dst buf semantics in src semantic range, src buf semantic is %s, affected dst buf "
305	            "semantics are as follows:",
306	            srcBufSemantic.Describe().c_str());
307	        for (auto& ele : affectedDstBufSemantics) {
308	            HCCL_ERROR("    %s", ele->Describe().c_str());
309	        }
310	        return ret;
311	    }
312	
313	    RankId dstRank = slicePair.dstRank;
314	    BufferType dstBufType = slicePair.dstSlice.GetType();
315	    // 分割尾节点
316	    BufferSemantic& lastDstBuf = *(affectedDstBufSemantics.back());
317	    if (lastDstBuf.startAddr + lastDstBuf.size > dstEndAddr) {
318	        BufferSemantic dstBufSemantic(
319	            dstEndAddr, lastDstBuf.startAddr + lastDstBuf.size - dstEndAddr, lastDstBuf.isReduce, lastDstBuf.reduceType,
320	            lastDstBuf.srcBufs);
321	        for (auto& srcBuf : dstBufSemantic.srcBufs) {
322	            srcBuf.srcAddr += dstEndAddr - lastDstBuf.startAddr;
323	        }
324	        dstBufSemantic.affectedGlobalSteps = lastDstBuf.affectedGlobalSteps;
325	
326	        allRankMemSemantics_[dstRank][dstBufType].insert(dstBufSemantic);
327	
328	        // 修改原来的节点
329	        lastDstBuf.size = dstEndAddr - lastDstBuf.startAddr;
330	    }
331	
332	    // 拆分首节点。（必须先新增尾节点，再修改首节点，因为fistDstBuf和lastDstBuf可能指向同一个对象）
333	    BufferSemantic& fistDstBuf = *(affectedDstBufSemantics[0]);
334	    if (fistDstBuf.startAddr < dstStartAddr) {
335	        BufferSemantic dstBufSemantic(
336	            dstStartAddr, fistDstBuf.startAddr + fistDstBuf.size - dstStartAddr, fistDstBuf.isReduce,
337	            fistDstBuf.reduceType, fistDstBuf.srcBufs);
338	        for (auto& srcBuf : dstBufSemantic.srcBufs) {
339	            srcBuf.srcAddr += dstStartAddr - fistDstBuf.startAddr;
340	        }
341	        dstBufSemantic.affectedGlobalSteps = fistDstBuf.affectedGlobalSteps;
342	
343	        allRankMemSemantics_[dstRank][dstBufType].insert(dstBufSemantic);
344	
345	        fistDstBuf.size = dstStartAddr - fistDstBuf.startAddr;
346	    }
347	
348	    std::vector<BufferSemantic*> toAddReduceInfoSemantics;
349	    GetAffectedBufSemantics(slicePair, srcBufSemantic, toAddReduceInfoSemantics);
350	
351	    ret = ReduceToAffectedBufSemantic(srcBufSemantic, toAddReduceInfoSemantics, srcStartAddr);
352	    if (ret != HcclResult::HCCL_SUCCESS) {
353	        HCCL_ERROR(
354	            "reduce to affected buf semantics failed, src buf semantic is %s, affected dst buf semantics are as "
355	            "follows:",
356	            srcBufSemantic.Describe().c_str());
357	        for (auto& ele : toAddReduceInfoSemantics) {
358	            HCCL_ERROR("    %s", ele->Describe().c_str());
359	        }
360	        return ret;
361	    }
362	
363	    return HcclResult::HCCL_SUCCESS;
364	}
365	
366	void TaskCheckOpSemantics::RemoveAffectedBufSemantics(
367	    SliceOpPair& slicePair, std::vector<BufferSemantic*>& affectedDstBufSemantics)
368	{
369	    u64 dstStartAddr = slicePair.dstSlice.GetOffset();
370	    u64 dstEndAddr = dstStartAddr + slicePair.dstSlice.GetSize();
371	
372	    RankId dstRank = slicePair.dstRank;
373	    BufferType dstBufType = slicePair.dstSlice.GetType();
374	    std::set<BufferSemantic>& targetBufferSemantic = allRankMemSemantics_[dstRank][dstBufType];
375	
376	    // 一种特殊情况，对应的dst还未创建起来
377	    if (affectedDstBufSemantics.size() == 0) {
378	        return;
379	    }
380	
381	    // 新增尾节点
382	    BufferSemantic& lastDstBuf = *(affectedDstBufSemantics.back());
383	    if (lastDstBuf.startAddr + lastDstBuf.size > dstEndAddr) {
384	        BufferSemantic dstBufSemantic(
385	            dstEndAddr, lastDstBuf.startAddr + lastDstBuf.size - dstEndAddr, lastDstBuf.isReduce, lastDstBuf.reduceType,
386	            lastDstBuf.srcBufs);
387	        for (auto& srcBuf : dstBufSemantic.srcBufs) {
388	            srcBuf.srcAddr += dstEndAddr - lastDstBuf.startAddr;
389	        }
390	        dstBufSemantic.affectedGlobalSteps = lastDstBuf.affectedGlobalSteps;
391	
392	        targetBufferSemantic.insert(dstBufSemantic);
393	        // 修改原来的节点
394	        lastDstBuf.size = dstEndAddr - lastDstBuf.startAddr;
395	    }
396	
397	    // 修改首节点。（必须先新增尾节点，再修改首节点，因为fistDstBuf和lastDstBuf可能指向同一个对象）
398	    BufferSemantic& fistDstBuf = *(affectedDstBufSemantics[0]);
399	    if (fistDstBuf.startAddr < dstStartAddr) {
400	        fistDstBuf.size = dstStartAddr - fistDstBuf.startAddr;
401	    }
402	
403	    for (auto ele : affectedDstBufSemantics) {
404	        if (ele->startAddr < dstStartAddr) {
405	            continue;
406	        }
407	        targetBufferSemantic.erase(*ele);
408	    }
409	
410	    return;
411	}
412	
413	HcclResult
414	TaskCheckOpSemantics::ApplySrcBufSemanticsToDst(SliceOpPair& slicePair, std::vector<BufferSemantic*> srcBufSemantics)
415	{
416	    SliceOp sliceOp = slicePair.sliceOp;
417	
418	    if (sliceOp == SliceOp::OVERRIDE) {
419	        std::vector<BufferSemantic*> affectedDstBufSemantics;
420	        GetAffectedBufSemantics(slicePair, affectedDstBufSemantics);
421	        RemoveAffectedBufSemantics(slicePair, affectedDstBufSemantics);
422	
423	        for (auto& ele : srcBufSemantics) {
424	            ApplyOverrideSrcBufSemantic(slicePair, *ele);
425	        }
426	    } else if (sliceOp == SliceOp::REDUCE) {
427	        for (auto& ele : srcBufSemantics) {
428	            std::vector<BufferSemantic*> affectedDstBufSemantics;
429	            GetAffectedBufSemantics(slicePair, *ele, affectedDstBufSemantics);
430	            auto ret = ApplyReduceSrcBufSemantic(slicePair, *ele, affectedDstBufSemantics);
431	            if (ret != HcclResult::HCCL_SUCCESS) {
432	                HCCL_ERROR(
433	                    "fail to apply reduce for src buf semantic, which is %s, affected dst buf semantics are as "
434	                    "follows:",
435	                    ele->Describe().c_str());
436	                for (auto& ele : affectedDstBufSemantics) {
437	                    HCCL_ERROR("    %s", ele->Describe().c_str());
438	                }
439	                return ret;
440	            }
441	        }
442	    }
443	    return HcclResult::HCCL_SUCCESS;
444	}
445	
446	HcclResult TaskCheckOpSemantics::ProcessSliceOpPair(SliceOpPair& slicePair)
447	{
448	    RankId srcRank = slicePair.srcRank;
449	    BufferType srcBufType = slicePair.srcSlice.GetType();
450	    u64 srcStartAddr = slicePair.srcSlice.GetOffset();
451	    u64 srcSize = slicePair.srcSlice.GetSize();
452	    if (srcSize == 0) {
453	        return HcclResult::HCCL_SUCCESS;
454	    }
455	
456	    // 根据源slice获取源数据片
457	    std::vector<BufferSemantic*> srcBufSemantics;
458	    for (auto& ele : allRankMemSemantics_[srcRank][srcBufType]) {
459	        if (ele.startAddr + ele.size <= srcStartAddr) {
460	            continue;
461	        }
462	
463	        if (ele.startAddr >= srcStartAddr + srcSize) {
464	            continue;
465	        }
466	
467	        srcBufSemantics.push_back(const_cast<BufferSemantic*>(&ele));
468	    }
469	
470	    auto ret = CheckBufSemantics(srcBufSemantics, srcStartAddr, srcSize, true);
471	    if (ret != HcclResult::HCCL_SUCCESS) {
472	        // 对于reduce操作，源slice对应的语义块不能有缺失，因为随机数据做reduce，可能导致概率性溢出问题
473	        if (slicePair.sliceOp == SliceOp::REDUCE) {
474	            HCCL_ERROR(
475	                "failed to check buf semantics in src slice, src slice is %s, bufSemantics in this range are as "
476	                "follows:",
477	                slicePair.srcSlice.Describe().c_str());
478	            for (auto& ele : srcBufSemantics) {
479	                HCCL_ERROR("    %s", ele->Describe().c_str());
480	            }
481	
482	            return HCCL_E_PARA;
483	        } else if (slicePair.sliceOp == SliceOp::OVERRIDE) {
484	            HCCL_WARNING("incomplete buf semantics in src slice, which may affected performance.");
485	        }
486	    }
487	
488	    // 将源数据片应用到目标数据片
489	    ret = ApplySrcBufSemanticsToDst(slicePair, srcBufSemantics);
490	    if (ret != HcclResult::HCCL_SUCCESS) {
491	        HCCL_ERROR(
492	            "failed to apply src buf semantics to dst, src slice is %s, bufSemantics in this range are as follows:",
493	            slicePair.srcSlice.Describe().c_str());
494	        for (auto& ele : srcBufSemantics) {
495	            HCCL_ERROR("    %s", ele->Describe().c_str());
496	        }
497	        return ret;
498	    }
499	    RankId dstRank = slicePair.dstRank;
500	    memSemanticsChange_[dstRank] = true;
501	
502	    return HcclResult::HCCL_SUCCESS;
503	}
504	
505	void TaskCheckOpSemantics::GetSliceOpPair(TaskNode* simNode, std::vector<SliceOpPair>& sliceOpPairs) const
506	{
507	    TaskTypeStub taskType = simNode->GetNodeType();
508	    if (taskType == TaskTypeStub::LOCAL_COPY) {
509	        const TaskStubLocalCopy* task = dynamic_cast<const TaskStubLocalCopy*>(simNode->task);
510	        SliceOpPair pair;
511	        pair.srcRank = simNode->rankIdx;
512	        pair.dstRank = simNode->rankIdx;
513	        pair.srcSlice = task->GetSrcSlice();
514	        pair.dstSlice = task->GetDstSlice();
515	        pair.sliceOp = SliceOp::OVERRIDE;
516	        sliceOpPairs.push_back(pair);
517	    } else if (taskType == TaskTypeStub::LOCAL_REDUCE) {
518	        const TaskStubLocalReduce* task = dynamic_cast<const TaskStubLocalReduce*>(simNode->task);
519	        SliceOpPair pair;
520	        pair.srcRank = simNode->rankIdx;
521	        pair.dstRank = simNode->rankIdx;
522	        pair.srcSlice = task->GetSrcSlice();
523	        pair.dstSlice = task->GetDstSlice();
524	        pair.sliceOp = SliceOp::REDUCE;
525	        sliceOpPairs.push_back(pair);
526	    } else if (taskType == TaskTypeStub::READ) {
527	        const TaskStubRead* readTask = dynamic_cast<const TaskStubRead*>(simNode->task);
528	        SliceOpPair pair;
529	        pair.srcRank = readTask->GetRemoteRank();
530	        pair.dstRank = simNode->rankIdx;
531	        pair.srcSlice = readTask->GetRemoteSlice();
532	        pair.dstSlice = readTask->GetLocalSlice();
533	        pair.sliceOp = SliceOp::OVERRIDE;
534	        sliceOpPairs.push_back(pair);
535	    } else if (taskType == TaskTypeStub::WRITE) {
536	        const TaskStubWrite* writeTask = dynamic_cast<const TaskStubWrite*>(simNode->task);
537	        SliceOpPair pair;
538	        pair.srcRank = simNode->rankIdx;
539	        pair.dstRank = writeTask->GetRemoteRank();
540	        pair.srcSlice = writeTask->GetLocalSlice();
541	        pair.dstSlice = writeTask->GetRemoteSlice();
542	        pair.sliceOp = SliceOp::OVERRIDE;
543	        sliceOpPairs.push_back(pair);
544	    } else if (taskType == TaskTypeStub::READ_REDUCE) {
545	        const TaskStubReadReduce* readReduceTask = dynamic_cast<const TaskStubReadReduce*>(simNode->task);
546	        SliceOpPair pair;
547	        pair.srcRank = readReduceTask->GetRemoteRank();
548	        pair.dstRank = simNode->rankIdx;
549	        pair.srcSlice = readReduceTask->GetRemoteSlice();
550	        pair.dstSlice = readReduceTask->GetLocalSlice();
551	        pair.sliceOp = SliceOp::REDUCE;
552	        sliceOpPairs.push_back(pair);
553	    } else if (taskType == TaskTypeStub::WRITE_REDUCE) {
554	        const TaskStubWriteReduce* writeReduceTask = dynamic_cast<const TaskStubWriteReduce*>(simNode->task);
555	        SliceOpPair pair;
556	        pair.srcRank = simNode->rankIdx;
557	        pair.dstRank = writeReduceTask->GetRemoteRank();
558	        pair.srcSlice = writeReduceTask->GetLocalSlice();
559	        pair.dstSlice = writeReduceTask->GetRemoteSlice();
560	        pair.sliceOp = SliceOp::REDUCE;
561	        sliceOpPairs.push_back(pair);
562	    } else if (taskType == TaskTypeStub::LOCAL_BATCH_REDUCE) {
563	        HCCL_ERROR("[TaskCheckOpSemantics::GetSliceOpPair] TaskType LOCAL_BATCH_REDUCE not support");
564	    }
565	    return;
566	}
567	
568	void TaskCheckOpSemantics::UpdateStep(TaskNode* simNode)
569	{
570	    RankId rankId = simNode->rankIdx;
571	    globalStep_++;
572	    if (localStep_.count(rankId) == 0) {
573	        localStep_[rankId] = 1;
574	    } else {
575	        localStep_[rankId] += 1;
576	    }
577	
578	    localStep2GlobalStep_[rankId][localStep_[rankId]] = globalStep_;
579	    globalStep2LocalStep_[globalStep_] = LocalStep{rankId, localStep_[rankId]};
580	
581	    simNode->globalStep = globalStep_;
582	    simNode->localStep = localStep_[rankId];
583	    return;
584	}
585	
586	u32 TaskCheckOpSemantics::GetCurLocalStep()
587	{
588	    // globalStep2LocalStep_ 的key一定是递增的，所以取最后一个就是当前的
589	    auto iter = globalStep2LocalStep_.end();
590	    iter--;
591	    return iter->second.localStep;
592	}
593	
594	HcclResult TaskCheckOpSemantics::DumpNodeSemantics(TaskNode* simNode)
595	{
596	    RankId rankId = simNode->rankIdx;
597	
598	    bool change = false;
599	    if (memSemanticsChange_.count(rankId) && memSemanticsChange_[rankId]) {
600	        change = true;
601	        memSemanticsChange_[rankId] = false;
602	    }
603	
604	    return HcclResult::HCCL_SUCCESS;
605	}
606	
607	HcclResult TaskCheckOpSemantics::ProcessNodeSemantics(TaskNode* simNode)
608	{
609	    // 更新localStep与globalStep
610	    UpdateStep(simNode);
611	
612	    std::vector<SliceOpPair> sliceOpPairs;
613	    GetSliceOpPair(simNode, sliceOpPairs);
614	
615	    HcclResult ret;
616	    for (auto& ele : sliceOpPairs) {
617	        ret = ProcessSliceOpPair(ele);
618	        if (ret != HcclResult::HCCL_SUCCESS) {
619	            simNode->genSemanticError = true; // 该节点产生语义信息失败，后续在可视化界面进行高亮
620	            HCCL_ERROR("process SliceOpPair failed,  SliceOpPair is %s", ele.Describe().c_str());
621	            return ret;
622	        }
623	    }
624	
625	    // 在这边dump语义信息，给可视化界面使用
626	
627	    return HcclResult::HCCL_SUCCESS;
628	}
629	
630	void TaskCheckOpSemantics::AddChildrenToQueue(
631	    TaskNode* node, std::set<TaskNode*>& visitedNodes, std::queue<TaskNode*>& walkQue,
632	    std::set<TaskNode*>& simulatedNodes) const
633	{
634	#ifdef HCCL_ALG_ANALYZER_DAVID
635	    node = Hccl::UpdateNodeForCcuGraph(node, simulatedNodes);
636	#endif
637	    for (auto& child : node->children) {
638	        if (visitedNodes.count(child) != 0) {
639	            continue;
640	        }
641	        walkQue.push(child);
642	        visitedNodes.insert(child);
643	    }
644	    return;
645	}
646	
647	HcclResult TaskCheckOpSemantics::GenMemSemantics()
648	{
649	    std::set<TaskNode*> visitedNodes;
650	    std::queue<TaskNode*> walkQue;
651	    std::set<TaskNode*> simulatedNodes;
652	
653	    // graphHead_是dummy节点，需要忽略掉的
654	    simulatedNodes.insert(graphHead_);
655	    for (auto& child : graphHead_->children) {
656	        visitedNodes.insert(child);
657	        walkQue.push(child);
658	    }
659	
660	    while (!walkQue.empty()) {
661	        TaskNode* curNode = walkQue.front();
662	        walkQue.pop();
663	
664	        // 因为Send/Recv或者SendReduce/RecvReduce必须成对执行，所以队列中有些节点可能已经执行
665	        if (simulatedNodes.count(curNode) != 0) {
666	            continue;
667	        }
668	
669	        // 父节点还没全部执行完成，不能执行
670	        if (!IsReadyForSimulate(curNode, simulatedNodes)) {
671	            walkQue.push(curNode);
672	            continue;
673	        }
674	
675	        auto ret = ProcessNodeSemantics(curNode);
676	        if (ret != HcclResult::HCCL_SUCCESS) {
677	            HCCL_ERROR("Process node semantics failed. Node task is %s", curNode->task->Describe().c_str());
678	            return ret;
679	        }
680	
681	        AddChildrenToQueue(curNode, visitedNodes, walkQue, simulatedNodes);
682	        simulatedNodes.insert(curNode);
683	    }
684	
685	    return HcclResult::HCCL_SUCCESS;
686	}
687	
688	HcclResult TaskCheckOpSemantics::Execute()
689	{
690	    if (opType_ == HcclCMDType::HCCL_CMD_BROADCAST || opType_ == HcclCMDType::HCCL_CMD_SCATTER) {
691	        InitInputBuffer(root_);
692	    } else {
693	        InitInputBuffer();
694	    }
695	
696	    HcclResult ret = HcclResult::HCCL_SUCCESS;
697	    if (graphHead_->hasAivTask) {
698	        HCCL_WARNING("[TaskCheckOpSemantics::Execute] not support AIV task");
699	    } else {
700	        ret = GenMemSemantics();
701	    }
702	
703	    if (ret != HcclResult::HCCL_SUCCESS) {
704	        HCCL_ERROR("Generate memory semantics failed.");
705	        return ret;
706	    }
707	    HCCL_INFO("gen GenMemSemantics success");
708	
709	    if (opType_ == HcclCMDType::HCCL_CMD_ALLREDUCE) {
710	        ret = TaskCheckAllReduceSemantics(allRankMemSemantics_, dataSize_, reduceType_);
711	    } else if (opType_ == HcclCMDType::HCCL_CMD_ALLGATHER) {
712	        ret = TaskCheckAllGatherSemantics(allRankMemSemantics_, dataSize_);
713	    } else if (opType_ == HcclCMDType::HCCL_CMD_ALLGATHER_V) {
714	        ret = TaskCheckAllGatherVSemantics(allRankMemSemantics_, vDataDes_);
715	    } else if (opType_ == HcclCMDType::HCCL_CMD_REDUCE_SCATTER) {
716	        ret = TaskCheckReduceScatterSemantics(allRankMemSemantics_, dataSize_, reduceType_);
717	    } else if (opType_ == HcclCMDType::HCCL_CMD_REDUCE_SCATTER_V) {
718	        ret = TaskCheckReduceScatterVSemantics(allRankMemSemantics_, reduceType_, vDataDes_);
719	    } else if (opType_ == HcclCMDType::HCCL_CMD_ALLTOALL || opType_ == HcclCMDType::HCCL_CMD_ALLTOALLVC) {
720	        ret = TaskCheckAll2AllSemantics(allRankMemSemantics_, all2AllDataDes_);
721	    } else if (opType_ == HcclCMDType::HCCL_CMD_ALLTOALLV) {
722	        ret = TaskCheckAll2AllVSemantics(allRankMemSemantics_, all2AllDataDes_);
723	    } else if (opType_ == HcclCMDType::HCCL_CMD_SEND || opType_ == HcclCMDType::HCCL_CMD_RECEIVE) {
724	        ret = TaskCheckSendRecvSemantics(allRankMemSemantics_, dataSize_, srcRank_, dstRank_);
725	    } else if (opType_ == HcclCMDType::HCCL_CMD_BROADCAST) {
726	        ret = TaskCheckBroadcastSemantics(allRankMemSemantics_, dataSize_, root_);
727	    } else if (opType_ == HcclCMDType::HCCL_CMD_REDUCE) {
728	        ret = TaskCheckReduceSemantics(allRankMemSemantics_, dataSize_, reduceType_, root_);
729	    } else if (opType_ == HcclCMDType::HCCL_CMD_SCATTER) {
730	        ret = TaskCheckScatterSemantics(allRankMemSemantics_, dataSize_, root_);
731	    } else if (opType_ == HcclCMDType::HCCL_CMD_BATCH_SEND_RECV) {
732	        ret = TaskCheckBatchSendRecvSemantics(allRankMemSemantics_, dataSize_);
733	    } else {
734	        HCCL_ERROR("unsupported op type[%d]", opType_);
735	        ret = HcclResult::HCCL_E_NOT_SUPPORT;
736	    }
737	    if (ret != HcclResult::HCCL_SUCCESS) {
738	        HCCL_ERROR("Check memory semantics failed.");
739	        return ret;
740	    }
741	    return HcclResult::HCCL_SUCCESS;
742	}
743	} // namespace HcclSim
